#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

typedef long long ll;

typedef struct {
    ll sum;
    int i;
    int j;
} Node;

typedef struct {
    Node* a;
    int size;
    int cap;
} MinHeap;

static int less_node(Node x, Node y) {
    if (x.sum != y.sum) return x.sum < y.sum;
    if (x.i != y.i) return x.i < y.i;
    return x.j < y.j;
}

static void heap_init(MinHeap* h, int cap) {
    h->a = (Node*)malloc((size_t)cap * sizeof(Node));
    h->size = 0;
    h->cap = cap;
}

static void heap_push(MinHeap* h, Node x) {
    int i = h->size++;
    h->a[i] = x;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (less_node(h->a[p], h->a[i])) break;
        if (h->a[p].sum == h->a[i].sum && h->a[p].i == h->a[i].i && h->a[p].j == h->a[i].j) break;
        Node tmp = h->a[p]; h->a[p] = h->a[i]; h->a[i] = tmp;
        i = p;
    }
}

static Node heap_pop(MinHeap* h) {
    Node root = h->a[0];
    h->a[0] = h->a[--h->size];
    int i = 0;
    while (1) {
        int l = 2 * i + 1, r = l + 1, s = i;
        if (l < h->size && less_node(h->a[l], h->a[s])) s = l;
        if (r < h->size && less_node(h->a[r], h->a[s])) s = r;
        if (s == i) break;
        Node tmp = h->a[i]; h->a[i] = h->a[s]; h->a[s] = tmp;
        i = s;
    }
    return root;
}

static void heap_free(MinHeap* h) {
    free(h->a);
}

static const char* skip_space(const char* p) {
    while (*p && isspace((unsigned char)*p)) ++p;
    return p;
}

static const char* read_token(const char* p, char* out, int out_cap) {
    p = skip_space(p);
    int depth = 0, len = 0;
    if (*p == '[') {
        do {
            if (*p == '[') ++depth;
            else if (*p == ']') --depth;
            if (len + 1 < out_cap) out[len++] = *p;
            ++p;
        } while (*p && depth > 0);
    } else {
        while (*p && *p != ',' && *p != ']') {
            if (len + 1 < out_cap) out[len++] = *p;
            ++p;
        }
    }
    out[len] = '\0';
    p = skip_space(p);
    if (*p == ',') ++p;
    return p;
}

static ll* parse_array(const char* s, int* n) {
    if (s[0] == '[' && s[1] == ']') {
        *n = 0;
        return NULL;
    }
    int cap = 16, size = 0;
    ll* a = (ll*)malloc((size_t)cap * sizeof(ll));
    const char* p = s + 1;
    while (*p && *p != ']') {
        char* endptr;
        p = skip_space(p);
        ll x = strtoll(p, &endptr, 10);
        if (p == endptr) break;
        if (size == cap) {
            cap *= 2;
            a = (ll*)realloc(a, (size_t)cap * sizeof(ll));
        }
        a[size++] = x;
        p = skip_space(endptr);
        if (*p == ',') ++p;
    }
    *n = size;
    return a;
}

static ll* kSmallestPairs(const ll* nums1, int m, const ll* nums2, int n,
                          int k, int* returnSize) {
    *returnSize = 0;
    if (m == 0 || n == 0 || k <= 0) return NULL;

    int limit = m < k ? m : k;
    MinHeap pq;
    heap_init(&pq, limit + 4);

    for (int i = 0; i < limit; ++i)
        heap_push(&pq, (Node){nums1[i] + nums2[0], i, 0});

    ll* result = (ll*)malloc((size_t)k * 2 * sizeof(ll));
    while (pq.size > 0 && *returnSize < k) {
        Node cur = heap_pop(&pq);
        int pos = (*returnSize) * 2;
        result[pos] = nums1[cur.i];
        result[pos + 1] = nums2[cur.j];
        ++(*returnSize);

        if (cur.j + 1 < n)
            heap_push(&pq, (Node){nums1[cur.i] + nums2[cur.j + 1], cur.i, cur.j + 1});
    }

    heap_free(&pq);
    return result;
}

int main(void) {
    char line[1000000];
    if (!fgets(line, sizeof(line), stdin)) return 0;

    const char* p = line;
    char tok1[500000], tok2[500000], tok3[64];
    p = skip_space(p);
    if (*p == '[') ++p;
    p = read_token(p, tok1, sizeof(tok1));
    p = read_token(p, tok2, sizeof(tok2));
    p = read_token(p, tok3, sizeof(tok3));

    int m = 0, n = 0;
    ll* nums1 = parse_array(tok1, &m);
    ll* nums2 = parse_array(tok2, &n);
    int k = atoi(tok3);

    int returnSize = 0;
    ll* result = kSmallestPairs(nums1, m, nums2, n, k, &returnSize);

    printf("[");
    for (int i = 0; i < returnSize; ++i) {
        if (i) printf(",");
        printf("[%lld,%lld]", result[2*i], result[2*i+1]);
    }
    printf("]\n");

    free(nums1);
    free(nums2);
    free(result);
    return 0;
}

