class Solution {
    struct Node {
        long long sum;
        int i, j;
    };
    struct Cmp {
        bool operator()(const Node& a, const Node& b) const {
            if (a.sum != b.sum) return a.sum > b.sum;
            if (a.i != b.i) return a.i > b.i;
            return a.j > b.j;
        }
    };
public:
    vector<vector<long long>> kSmallestPairs(const vector<long long>& nums1,
                                             const vector<long long>& nums2,
                                             int k) {
        vector<vector<long long>> ans;
        int m = (int)nums1.size(), n = (int)nums2.size();
        if (m == 0 || n == 0 || k <= 0) return ans;

        priority_queue<Node, vector<Node>, Cmp> pq;
        int limit = min(m, k);
        for (int i = 0; i < limit; ++i)
            pq.push({nums1[i] + nums2[0], i, 0});

        while (!pq.empty() && (int)ans.size() < k) {
            Node cur = pq.top();
            pq.pop();
            ans.push_back({nums1[cur.i], nums2[cur.j]});
            if (cur.j + 1 < n) {
                int nj = cur.j + 1;
                pq.push({nums1[cur.i] + nums2[nj], cur.i, nj});
            }
        }
        return ans;
    }
};

static vector<string> splitTop(const string& s) {
    string t = s;
    if (t.size() >= 2 && t.front() == '[' && t.back() == ']')
        t = t.substr(1, t.size() - 2);
    vector<string> out;
    int depth = 0, start = 0;
    for (int i = 0; i < (int)t.size(); ++i) {
        if (t[i] == '[') ++depth;
        else if (t[i] == ']') --depth;
        else if (t[i] == ',' && depth == 0) {
            out.push_back(t.substr(start, i - start));
            start = i + 1;
        }
    }
    if (start < (int)t.size()) out.push_back(t.substr(start));
    for (string& x : out) {
        size_t l = x.find_first_not_of(" \t");
        size_t r = x.find_last_not_of(" \t");
        x = (l == string::npos) ? "" : x.substr(l, r - l + 1);
    }
    return out;
}

