import java.io.*;
import java.util.*;

class Solution {
    private static class Node {
        long sum;
        int i, j;
        Node(long sum, int i, int j) {
            this.sum = sum;
            this.i = i;
            this.j = j;
        }
    }

    public List<List<Long>> kSmallestPairs(long[] nums1, long[] nums2, int k) {
        List<List<Long>> ans = new ArrayList<>();
        int m = nums1.length, n = nums2.length;
        if (m == 0 || n == 0 || k <= 0) return ans;

        PriorityQueue<Node> pq = new PriorityQueue<>((a, b) -> {
            int c = Long.compare(a.sum, b.sum);
            if (c != 0) return c;
            c = Integer.compare(a.i, b.i);
            if (c != 0) return c;
            return Integer.compare(a.j, b.j);
        });

        int limit = Math.min(m, k);
        for (int i = 0; i < limit; i++) {
            pq.offer(new Node(nums1[i] + nums2[0], i, 0));
        }

        while (!pq.isEmpty() && ans.size() < k) {
            Node cur = pq.poll();
            ans.add(Arrays.asList(nums1[cur.i], nums2[cur.j]));
            if (cur.j + 1 < n) {
                int nj = cur.j + 1;
                pq.offer(new Node(nums1[cur.i] + nums2[nj], cur.i, nj));
            }
        }
        return ans;
    }
}

public class Main {
    static String[] splitTop(String s) {
        s = s.trim();
        if (s.equals("[]")) return new String[0];
        s = s.substring(1, s.length() - 1);
        List<String> parts = new ArrayList<>();
        int depth = 0, start = 0;
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '[') depth++;
            else if (c == ']') depth--;
            else if (c == ',' && depth == 0) {
                parts.add(s.substring(start, i).trim());
                start = i + 1;
            }
        }
        if (start < s.length()) parts.add(s.substring(start).trim());
        return parts.toArray(new String[0]);
    }

    static long[] toLongArray(String s) {
        String[] parts = splitTop(s);
        long[] a = new long[parts.length];
        for (int i = 0; i < parts.length; i++) a[i] = Long.parseLong(parts[i]);
        return a;
    }

    static String pairListToJson(List<List<Long>> pairs) {
        StringBuilder sb = new StringBuilder("[");
        for (int i = 0; i < pairs.size(); i++) {
            if (i > 0) sb.append(',');
            sb.append('[').append(pairs.get(i).get(0)).append(',')
              .append(pairs.get(i).get(1)).append(']');
        }
        return sb.append(']').toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String line = br.readLine();
        String[] outer = splitTop(line);
        long[] nums1 = toLongArray(outer[0]);
        long[] nums2 = toLongArray(outer[1]);
        int k = Integer.parseInt(outer[2]);
        List<List<Long>> result = new Solution().kSmallestPairs(nums1, nums2, k);
        System.out.println(pairListToJson(result));
    }
}

